import{at as e,it as t,n,vt as r}from"./chunks/framework.BFUVyeTq.js";var i=JSON.parse(`{"title":"Upgrade Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/upgrade-guide.md","filePath":"guide/getting-started/upgrade-guide.md"}`),a={name:`guide/getting-started/upgrade-guide.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to “Upgrade Guide”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">TODO</p><p>Write this page. Some breaking changes to cover:</p><ul><li>Properties not declared in the schema are no longer treated as attributes (they behave like normal class properties), and magic properties (relations, computed attributes, timestamps) are read-only.</li><li>Properties assigned in <code>initialize</code> must use <code>declare</code> without a default value, and the second argument of <code>initialize</code> is now an options object instead of the <code>exists</code> boolean.</li><li>The <code>LocalStorageEngine</code>, <code>FakeEngine</code>, and <code>LogEngine</code> engines have been removed.</li><li>Filters are no longer supported for retrieving models (field filters, <code>$contains</code>, and <code>$or</code>), you&#39;ll need to filter the results yourself after calling <code>all()</code>.</li><li>The <code>authorizations</code> relation in Solid models has been removed. Use <code>fetchPermissions</code> instead, and read authorizations using <code>requireWACAuthorizations</code> (or <code>requireACPAccessControlResources</code> for ACP). <code>isPublic</code> and <code>isPrivate</code> are now methods instead of getters, and they require calling <code>fetchPermissions</code> first (<code>fetchPublicPermissions</code> has been removed).</li><li>Relations no longer infer foreign key names from model names, so the foreign key must always be declared. Local keys are no longer supported either, related models are always matched using their <code>url</code>.</li><li>Attribute getter and setter methods (such as <code>getNicknameAttribute()</code> and <code>setNicknameAttribute(value)</code>) have been removed. Use native JavaScript getters and setters instead (see <a href="./../core-concepts/models.html#attribute-getters-and-setters">Attribute getters and setters</a>), keeping in mind that these can&#39;t override reading or writing real attributes.</li><li>Model configuration that used to be declared with static properties is now declared in the schema. For example, <code>static timestamps = [TimestampField.CreatedAt]</code> becomes <code>timestamps: [TimestampFields.CreatedAt]</code>, and <code>static mintsUrls = false</code> becomes <code>mintsUrls: false</code>.</li><li>Field definitions no longer support <code>get</code>, <code>set</code>, <code>serialize</code>, and <code>deserialize</code> hooks. Use native JavaScript getters and setters instead of <code>get</code> and <code>set</code>, and <a href="./../advanced/interoperability.html#custom-casts"><code>rdfCast()</code></a> instead of <code>serialize</code> and <code>deserialize</code>. Keep in mind that <code>rdfCast()</code> works with RDF values, and that array fields receive the entire array. If you were using <code>deserialize</code> to validate or normalize values (for example, discarding unknown values), you can use Zod methods such as <code>.catch()</code>, <code>z.preprocess()</code>, or <code>.transform()</code> instead; though these also run when attributes are set, not only when they&#39;re read.</li></ul></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};